package android.net;import java.util.*;public class NetworkRequest {public final Set<Integer> transports=new HashSet<>(),capabilities=new HashSet<>();public static class Builder {private final NetworkRequest r=new NetworkRequest();public Builder addTransportType(int n){r.transports.add(n);return this;}public Builder addCapability(int n){r.capabilities.add(n);return this;}public NetworkRequest build(){return r;}}}
